CREATE TABLE "CORE_GRGR_GROUP" (
  "GRGR_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "GRGR_NUM" varchar(20) UNIQUE NOT NULL,
  "ST_CD" char(2) NOT NULL,
  "EFF_DT" date NOT NULL,
  "TERM_DT" date,
  "CRTD_TS" timestamptz NOT NULL,
  "UPDT_TS" timestamptz NOT NULL
);

CREATE TABLE "CORE_PLPL_PLAN" (
  "PLPL_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "PLPL_CD" varchar(20) UNIQUE NOT NULL,
  "PLPL_NM" varchar(200) NOT NULL,
  "LOB_CD" varchar(30) NOT NULL,
  "EFF_DT" date NOT NULL,
  "TERM_DT" date,
  "CRTD_TS" timestamptz NOT NULL,
  "UPDT_TS" timestamptz NOT NULL
);

CREATE TABLE "CORE_MESB_SUBSCRIBER" (
  "MESB_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "SBSB_NUM" varchar(30) UNIQUE NOT NULL,
  "GRGR_ID" bigint NOT NULL,
  "FST_NM" varchar(100) NOT NULL,
  "LST_NM" varchar(100) NOT NULL,
  "DOB" date NOT NULL,
  "GNDR_CD" char(1),
  "CRTD_TS" timestamptz NOT NULL,
  "UPDT_TS" timestamptz NOT NULL
);

CREATE TABLE "CORE_MEME_MEMBER" (
  "MEME_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "MESB_ID" bigint NOT NULL,
  "RLTN_CD" varchar(2) NOT NULL,
  "FST_NM" varchar(100) NOT NULL,
  "LST_NM" varchar(100) NOT NULL,
  "DOB" date NOT NULL,
  "GNDR_CD" char(1),
  "IS_ACT" Boolean NOT NULL,
  "CRTD_TS" timestamptz NOT NULL,
  "UPDT_TS" timestamptz NOT NULL
);

CREATE TABLE "CORE_SBAD_ADDRESS" (
  "SBAD_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "MEME_ID" bigint NOT NULL,
  "ADR_TYP" varchar(10) NOT NULL,
  "ADR_LN1" varchar(150) NOT NULL,
  "ADR_LN2" varchar(150),
  "CITY_NM" varchar(100) NOT NULL,
  "ST_CD" char(2) NOT NULL,
  "ZIP_CD" varchar(10) NOT NULL,
  "EFF_DT" date NOT NULL,
  "CRTD_TS" timestamptz NOT NULL
);

CREATE TABLE "CORE_MEEN_ENROLLMENT" (
  "MEEN_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "MEME_ID" bigint NOT NULL,
  "PLPL_ID" bigint NOT NULL,
  "TXN_ID" bigint NOT NULL,
  "MAINT_TYP_CD" varchar(3) NOT NULL,
  "EFF_DT" date NOT NULL,
  "TERM_DT" date,
  "ENRL_STAT" varchar(15) NOT NULL,
  "CRTD_TS" timestamptz NOT NULL,
  "UPDT_TS" timestamptz NOT NULL
);

CREATE TABLE "ENRL_EDXN_TRANSACTION" (
  "TXN_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "FILE_NM" varchar(255) NOT NULL,
  "ISA_CTRL_NUM" varchar(20) NOT NULL,
  "GS_CTRL_NUM" varchar(20) NOT NULL,
  "ST_CTRL_NUM" varchar(20) NOT NULL,
  "SNDR_ID" varchar(20) NOT NULL,
  "RCVR_ID" varchar(20) NOT NULL,
  "RCVD_TS" timestamptz NOT NULL,
  "PROC_STAT" varchar(15) NOT NULL,
  "REC_CNT" int
);

CREATE TABLE "ENRL_RJRW_REJECT" (
  "RJRW_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "TXN_ID" bigint NOT NULL,
  "SRC_ROW" text NOT NULL,
  "RJCT_CD" varchar(20) NOT NULL,
  "RJCT_RSN" varchar(255) NOT NULL,
  "RJCT_TS" timestamptz NOT NULL
);

